import {categories, foods, bases, inputs, articles, topics, eventExample, categoryName, baseName} from './data.js';
import {icon} from './icons.js';
export const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const image=(name,alt,cls='',eager=false)=>`<img class="${cls}" src="./assets/${name}.png" alt="${alt}" width="960" height="720" loading="${eager?'eager':'lazy'}" decoding="async">`;
const link=(href,text,cls='text-link')=>`<a class="${cls}" href="${href}">${text}${icon('arrow')}</a>`;
const demoNote=(text='当前为界面示意。图片、产品及基地名称用于演示，真实资料待补充。')=>`<p class="demo-note">${icon('file')}<span>${text}</span></p>`;
const fields=items=>`<dl class="field-list">${items.map(([a,b])=>`<div><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl>`;
const crumbs=(parent,href,title)=>`<div class="breadcrumbs"><a href="#home">首页</a><span>/</span><a href="${href}">${parent}</a><span>/</span><span>${title}</span></div>`;
const pageHeader=(title,description,extra='')=>`<header class="page-header"><h1>${title}</h1><p>${description}</p>${extra}</header>`;
export const footer=()=>`<footer class="footer"><div><a class="footer-brand" href="#home">菌养食材</a><p>了解食材，连接基地与生产记录。</p></div><div class="footer-links"><a href="#about">网站介绍</a><a href="#about">采购与合作</a><button data-top type="button">返回顶部 ${icon('down')}</button></div><p class="footer-note">界面演示 · 产品、基地与检测资料待补充</p></footer>`;
export const foodCards=items=>items.map(x=>`<article class="product-card"><a href="#food/${x.id}" class="image-link" tabindex="-1" aria-hidden="true">${image(x.image,x.name+'摄影示意')}</a><div class="card-info"><span class="muted-label">${categoryName(x.category)}</span><h2><a href="#food/${x.id}">${x.name}</a></h2><p>${baseName(x.base)}</p><p>规格待补充 · 价格待补充</p><div class="card-bottom"><span class="status-text">检测资料待补充</span>${link('#food/'+x.id,'查看详情')}</div></div></article>`).join('');
export const emptyState=(title,desc,button='')=>`<div class="empty-state">${icon('file')}<h2>${title}</h2><p>${desc}</p>${button}</div>`;
export function homeView(){return `
  <section id="section-home" data-section="home" class="home-intro">
    <div class="hero">
      <div class="hero-photo">${image('hero','田园中篮装蔬菜的食材摄影示意','',true)}</div>
      <div class="hero-copy"><h1>了解菌养食材<br>看见生产与<br>检测过程</h1><p>连接食材、基地与生产记录</p><div class="button-row">${link('#foods','浏览菌养食材','button primary')}${link('#bases','查看基地溯源','button secondary')}</div></div>
      <a class="explore" href="#section/intro" data-explore><span>向下探索</span>${icon('down')}</a>
    </div>
    <div class="intro-block section-padding" id="intro"><div class="section-head"><h2>从微生物，<br class="mobile-break">到日常食材</h2><p>介绍微生物技术在种植与养殖中的应用，<br>连接食材、肥料与饲料，以及基地的生产和检测记录。</p></div><div class="intro-photo">${image('base','菜地、温室与山景的基地摄影示意')}</div><div class="process-strip">${[['sprout','微生物技术'],['sun','种植与养殖'],['leaf','食材'],['shield','检测与溯源']].map(([i,t],n)=>`<div>${icon(i)}<span>${t}</span>${n<3?icon('arrow','process-arrow'):''}</div>`).join('')}</div>${link('#article/principles','了解菌养机理')}</div>
  </section>
  <section id="section-food" data-section="food" class="section-padding food-section"><div class="section-head inline-head"><div><h2>菌养食材</h2><p>蔬菜、瓜果、家禽肉与蛋奶</p></div>${link('#foods','查看全部食材')}</div><div class="category-grid">${categories.map(x=>`<a href="#foods?category=${x.id}" class="category-item">${image(x.image,x.name+'分类摄影示意')}<h3>${x.name}</h3><span>浏览食材 ${icon('arrow')}</span></a>`).join('')}</div><p class="quiet-note">食材图片用于分类展示，实际产品、价格与批次资料待补充。</p></section>
  <section id="section-inputs" data-section="inputs" class="section-padding inputs-section"><div class="section-head"><h2>肥料与饲料</h2><p>了解投入品，探索种植与养殖的生产过程。</p></div><div class="inputs-grid"><article>${image('fertilizer','幼苗、根系与土壤的肥料栏目示意')}<h3>微生物肥料</h3><p>查看分类、成分、适用对象与使用方法。</p>${link('#inputs?type=fertilizer','了解肥料','button primary')}</article><article>${image('feed','木勺中的谷物与颗粒饲料示意')}<h3>发酵饲料</h3><p>了解原料、菌种、适用动物与储存说明。</p>${link('#inputs?type=feed','了解饲料','button primary')}</article></div></section>
  <section id="section-base" data-section="base" class="section-padding base-section"><div class="base-feature"><div class="base-photo">${image('base','种植基地摄影示意')}</div><div class="base-copy"><h2>基地溯源</h2><h3>看见食材的<br>生产过程</h3><p>生产记录 · 日常管理 · 指标监测</p><div class="button-row">${link('#bases','查看基地','button primary')}${link('#bases?view=process','查看生产过程','button secondary')}</div><p class="quiet-note">示意图，不代表实际基地</p></div></div></section>
  <section id="section-knowledge" data-section="knowledge" class="section-padding knowledge-section"><div class="knowledge-layout"><div><div class="section-head inline-head"><h2>科普知识</h2>${link('#articles','全部文章')}</div><div class="article-rows">${articles.slice(0,3).map(x=>`<a href="#article/${x.id}" class="article-row"><div><h3>${x.title}</h3><p>${x.intro}</p></div><span>阅读 ${icon('arrow')}</span></a>`).join('')}</div></div>${image('fertilizer','土壤中的幼苗与根系示意','knowledge-photo')}</div></section>
  <section id="section-events" data-section="events" class="section-padding events-section"><div class="section-head"><h2>食材安全事件</h2><p>按风险类型与年份检索，关注原始信息来源。</p></div><div class="event-shortcuts">${link('#events?risk=residue','农药残留','topic-link')}${link('#events?risk=metal','重金属','topic-link')}${link('#events','年份索引','topic-link')}</div><div class="event-intro"><p>事件资料整理中。正式内容将展示发生时间、涉及食材、调查信息与来源。</p>${link('#events','查看事件','button primary')}</div></section>${footer()}`;}

export function foodsView(route){return `<div class="page-shell">${pageHeader('菌养食材','从产品到基地，查看关联的生产与检测资料。')}${demoNote()}<form id="food-filters" class="filter-bar" role="search" aria-label="食材筛选"><label>食材类别<select name="category"><option value="all">全部类别</option>${categories.map(x=>`<option value="${x.id}" ${route.query.category===x.id?'selected':''}>${x.name}</option>`).join('')}</select></label><label>来源基地<select name="base"><option value="all">全部基地</option>${bases.map(x=>`<option value="${x.id}" ${route.query.base===x.id?'selected':''}>${x.name}</option>`).join('')}</select></label><label class="search-field">搜索食材<div>${icon('search')}<input name="search" type="search" placeholder="输入食材名称" value="${escapeHTML(route.query.search||'')}"></div></label><button class="reset-button" type="reset">重置筛选</button></form><p id="food-count" class="result-count" role="status"></p><div id="food-grid" class="product-grid"></div></div>${footer()}`;}

export function foodView(id){const x=foods.find(x=>x.id===id);if(!x)return missingView();return `<div class="page-shell">${crumbs('菌养食材','#foods',x.name)}<div class="detail-hero">${image(x.image,x.name+'示意照片','detail-image',true)}<div><span class="muted-label">${categoryName(x.category)} · 版式示意</span><h1>${x.name}</h1><p class="lead">连接产品、来源基地与对应批次记录。</p>${fields([['产品规格','待补充'],['参考价格','待补充'],['来源基地',`<a href="#base/${x.base}">${baseName(x.base)} ${icon('arrow')}</a>`],['批次编号','待补充']])}<div class="button-row">${link('#base/'+x.base+'?tab=process','查看生产过程','button primary')}<a class="button secondary" href="#reports" data-jump="reports">查看检测资料 ${icon('file')}</a></div></div></div>${demoNote()}<section class="detail-section"><h2>产品与批次信息</h2>${fields([['种植或养殖周期','待补充'],['采收或出栏日期','待补充'],['产地地址','待补充']])}</section><section class="detail-section" id="reports"><h2>检测资料</h2>${emptyState('资料待补充','目前没有对应批次的检测报告，暂不展示检测结果或合格结论。')}<div class="table-scroll"><table><caption>检测资料预留字段</caption><thead><tr><th>检测项目</th><th>结果及单位</th><th>判定依据</th><th>检测日期 / 机构</th></tr></thead><tbody><tr><td colspan="4">报告、检测项目及结果待补充</td></tr></tbody></table></div></section>${link('#foods','返回食材列表','back-link')}</div>${footer()}`;}

export function inputsView(route){const type=route.query.type==='feed'?'feed':'fertilizer';return `<div class="page-shell">${pageHeader('肥料与饲料','查看产品分类、成分、适用对象、使用方法与质量资料。')}${demoNote()}<div class="tabs" role="tablist" aria-label="投入品分类"><button role="tab" id="tab-fertilizer" aria-controls="inputs-panel" aria-selected="${type==='fertilizer'}" tabindex="${type==='fertilizer'?0:-1}" data-input-tab="fertilizer">肥料</button><button role="tab" id="tab-feed" aria-controls="inputs-panel" aria-selected="${type==='feed'}" tabindex="${type==='feed'?0:-1}" data-input-tab="feed">饲料</button></div><div id="inputs-panel" role="tabpanel" aria-labelledby="tab-${type}">${inputCards(type)}</div></div>${footer()}`;}
export const inputCards=type=>`<div class="input-list">${inputs.filter(x=>x.type===type).map(x=>`<article class="input-feature">${image(x.image,x.name+'摄影示意')}<div><h2>${x.name}</h2><p>${x.description}</p>${fields([['分类与成分','待补充'],['规格与价格','待补充'],['质量资料','待补充']])}${link('#input/'+x.id,'查看产品资料','button primary')}</div></article>`).join('')}</div>`;
export function inputView(id){const x=inputs.find(x=>x.id===id);if(!x)return missingView();const feed=x.type==='feed';return `<div class="page-shell">${crumbs('肥料与饲料','#inputs?type='+x.type,x.name)}<div class="detail-hero">${image(x.image,x.name+'摄影示意','detail-image',true)}<div><h1>${x.name}</h1><p class="lead">${x.description}</p>${fields([['产品类别',feed?'饲料示意':'肥料示意'],['规格与价格','待补充'],[feed?'原料与菌种':'成分与菌种','待补充'],[feed?'适用动物':'适用对象','待补充']])}</div></div>${demoNote()}<section class="detail-section"><h2>${feed?'使用与储存说明':'使用对象与方法'}</h2><p>具体产品说明与适用条件待补充。</p></section><section class="detail-section"><h2>标准及质量资料</h2>${emptyState('资料待补充','产品质量资料、适用标准及来源待核实后展示。')}</section><section class="detail-section"><h2>机理与应用说明</h2><p>技术资料与产品使用说明分别呈现。</p>${link('#articles?topic=methods','阅读技术方法')}</section>${link('#inputs?type='+x.type,'返回产品列表','back-link')}</div>${footer()}`;}

export function basesView(route){return `<div class="page-shell">${pageHeader('基地溯源',route.query.view==='process'?'先选择基地，再查看对应生产过程与批次资料。':'从基地介绍，探索生产过程、日常管理与指标监测。')}${demoNote()}<div class="base-list">${bases.map(x=>`<article class="base-card">${image(x.image,x.name+'摄影示意')}<div><span class="muted-label">${x.kind} · 所在地待补充</span><h2>${x.name}</h2><p>${x.description}</p>${link('#base/'+x.id+(route.query.view==='process'?'?tab=process':''),'查看基地','button primary')}</div></article>`).join('')}</div></div>${footer()}`;}
const baseTabs=[['intro','基地介绍'],['process','生产过程'],['management','日常管理'],['monitoring','指标监测'],['foods','关联食材']];
export function basePanel(x,tab){
  if(tab==='process')return `<h2>${x.kind==='种植'?'种植':'养殖'}过程</h2><p class="quiet-note">以下为流程字段示意，实际批次、日期、照片与记录待补充。</p><ol class="timeline">${(x.kind==='种植'?['播种','主要生产阶段','投入品使用','采收']:['入栏','主要养殖阶段','饲喂记录','出栏']).map((v,i)=>`<li><span class="timeline-dot">${String(i+1).padStart(2,'0')}</span><div><h3>${v}</h3><p>日期与生产记录待补充</p></div></li>`).join('')}</ol>`;
  if(tab==='management')return `<h2>日常管理</h2>${fields((x.kind==='种植'?['施肥记录','病虫害防治','清洁管理']:['饲喂记录','清洁管理','日常巡查']).map(x=>[x,'实际记录待补充']))}`;
  if(tab==='monitoring')return `<h2>指标监测</h2><p>环境监测与食材检测分别整理，明确采样对象、日期和资料来源。</p>${emptyState('监测资料待补充','未提供实际监测结果，不预设指标结论。')}<div class="table-scroll"><table><caption>监测资料字段</caption><thead><tr><th>采样对象</th><th>指标 / 单位</th><th>采样日期</th><th>结果 / 报告</th></tr></thead><tbody><tr><td colspan="4">实际监测资料待补充</td></tr></tbody></table></div>`;
  if(tab==='foods')return `<h2>关联食材</h2><p class="quiet-note">以下展示页面关系示意，不代表真实基地供货。</p><div class="product-grid">${foodCards(foods.filter(y=>y.base===x.id))}</div>`;
  return `<h2>基地介绍</h2>${fields([['基地名称','实际名称待补充'],['所在地','实际地址待补充'],['类型',x.kind],['生产与管理资料','待补充']])}<p>${x.description}</p>`;
}
export function baseView(id,route){const x=bases.find(x=>x.id===id);if(!x)return missingView();const tab=baseTabs.some(y=>y[0]===route.query.tab)?route.query.tab:'intro';return `<div class="page-shell">${crumbs('基地溯源','#bases',x.name)}${pageHeader(x.name,'连接基地、生产过程与食材资料。')}${image(x.image,x.name+'摄影示意','base-banner',true)}${demoNote()}<div class="tabs base-tabs" role="tablist" aria-label="基地资料">${baseTabs.map(([id,label])=>`<button role="tab" id="base-tab-${id}" aria-controls="base-panel" aria-selected="${tab===id}" tabindex="${tab===id?0:-1}" data-base-tab="${id}">${label}</button>`).join('')}</div><div id="base-panel" class="base-panel" role="tabpanel" aria-labelledby="base-tab-${tab}">${basePanel(x,tab)}</div>${link('#bases','返回基地列表','back-link')}</div>${footer()}`;}

export const articleRows=items=>items.map(x=>`<a href="#article/${x.id}" class="article-row"><div><span class="muted-label">${topics.find(y=>y.id===x.topic)?.name}</span><h2>${x.title}</h2><p>${x.intro}</p></div><span>阅读 ${icon('arrow')}</span></a>`).join('');
export function articlesView(route){const topic=topics.some(x=>x.id===route.query.topic)?route.query.topic:'all';return `<div class="page-shell">${pageHeader('科普知识','了解微生物、菌养机理、技术方法与检测资料。')}<div class="knowledge-browser"><nav class="topic-nav" aria-label="文章主题">${topics.map(x=>`<a href="#articles?topic=${x.id}" ${topic===x.id?'aria-current="page"':''}>${x.name}</a>`).join('')}</nav><div class="article-list">${articleRows(articles.filter(x=>topic==='all'||x.topic===topic))}</div></div></div>${footer()}`;}
export function articleView(id){const x=articles.find(x=>x.id===id);if(!x)return missingView();return `<div class="page-shell article-shell">${crumbs('科普知识','#articles',x.title)}${pageHeader(x.title,x.intro)}${image(x.image,x.title+'摄影示意','article-cover',true)}${demoNote('当前为文章版式与栏目介绍示意，正式内容和引用来源待补充。')}<div class="article-body">${x.sections.map(([t,p])=>`<section><h2>${t}</h2><p>${p}</p></section>`).join('')}</div>${link('#articles','返回科普列表','back-link')}</div>${footer()}`;}

export function eventsView(route){return `<div class="page-shell">${pageHeader('食材安全事件','按风险类型与年份检索，查看事件与原始信息来源。')}<form id="event-filters" class="filter-bar" aria-label="事件筛选"><label>风险类型<select name="risk"><option value="all">全部类型</option><option value="residue" ${route.query.risk==='residue'?'selected':''}>农药残留</option><option value="metal" ${route.query.risk==='metal'?'selected':''}>重金属</option></select></label><label>年份索引<input name="year" type="number" min="1900" max="2100" placeholder="输入年份" value="${escapeHTML(route.query.year||'')}"></label><button class="reset-button" type="reset">重置筛选</button></form><p id="event-count" class="result-count" role="status"></p>${emptyState('事件资料整理中','正式内容将提供事件名称、发生时间、涉及食材、调查与处理信息及原始来源。')}${link('#event/layout-example','查看事件详情版式')}</div>${footer()}`;}
export function eventView(id){if(id!==eventExample.id)return missingView();return `<div class="page-shell article-shell">${crumbs('食材安全事件','#events',eventExample.title)}${pageHeader(eventExample.title,eventExample.intro)}${demoNote('本页仅展示详情页面结构，未填入任何真实事件或调查结果。')}${['事件概况','涉及食材与风险类型','抽检或调查结果','官方处理信息','原始来源'].map(t=>`<section class="detail-section"><h2>${t}</h2><p>资料待整理；正式内容需保留发生日期、发布日期与原始来源。</p></section>`).join('')}${link('#events','返回事件列表','back-link')}</div>${footer()}`;}
export function aboutView(){return `<div class="page-shell article-shell">${pageHeader('关于菌养食材','了解食材，连接基地与生产记录。')}<div class="article-body"><section><h2>网站介绍</h2><p>介绍微生物技术在种植与养殖中的应用，展示菌养食材、肥料与饲料，提供基地生产记录和检测信息查询，支持相关产业的数据积累与科技研发。</p></section><section><h2>采购与合作咨询</h2>${fields([['运营主体','待补充'],['联系地址','待补充'],['电话 / 邮箱','待补充']])}</section></div>${link('#home','返回首页','button primary')}</div>${footer()}`;}
export function missingView(){return `<div class="page-shell">${pageHeader('这个页面暂时不存在','你可以返回首页，或使用左侧导航继续浏览。')}${link('#home','返回首页','button primary')}</div>${footer()}`;}

